8: fn make_osd_payload(
9:     lat_deg: f64,
10:     lon_deg: f64,
11:     height_m: f64,
12:     fly_time_s: f64,
13:     speed_mps: f64,
14:     is_motor_up: bool,
15:     mode_u8: u8,
16: ) -> [u8; 53] {
17:     let mut buf = [0u8; 53];
18:     LittleEndian::write_f64(&mut buf[0..8], lon_deg.to_radians());
19:     LittleEndian::write_f64(&mut buf[8..16], lat_deg.to_radians());
20:     LittleEndian::write_i16(&mut buf[16..18], (height_m * 10.0).round() as i16);
21:     LittleEndian::write_i16(&mut buf[18..20], (speed_mps * 10.0).round() as i16);
22:     if is_motor_up {
23:         buf[30] |= 0x08;
24:     }
25:     let status = 0x80u32 | (mode_u8 as u32 & 0x7F);
26:     LittleEndian::write_u32(&mut buf[32..36], status);
27:     let fly_time_ds = (fly_time_s * 10.0).round() as u16;
28:     LittleEndian::write_u16(&mut buf[42..44], fly_time_ds);
29:     buf
30: }
