32: fn make_gimbal_payload(pitch_deg: f64, mode_raw: u8) -> [u8; 7] {
33:     let mut buf = [0u8; 7];
34:     LittleEndian::write_i16(&mut buf[0..2], (pitch_deg * 10.0).round() as i16);
35:     buf[6] = (mode_raw & 0x03) << 6;
36:     buf
37: }
