39: fn make_rc_payload(
40:     aileron_norm: f64,
41:     elevator_norm: f64,
42:     throttle_norm: f64,
43:     rudder_norm: f64,
44:     signal_quality: u8,
45: ) -> [u8; 14] {
46:     let mut buf = [0u8; 14];
47:     let aileron = (1024.0 + aileron_norm * 660.0).round() as i16;
48:     let elevator = (1024.0 + elevator_norm * 660.0).round() as i16;
49:     let throttle = (1024.0 + throttle_norm * 660.0).round() as i16;
50:     let rudder = (1024.0 + rudder_norm * 660.0).round() as i16;
51:     LittleEndian::write_i16(&mut buf[0..2], aileron);
52:     LittleEndian::write_i16(&mut buf[2..4], elevator);
53:     LittleEndian::write_i16(&mut buf[4..6], throttle);
54:     LittleEndian::write_i16(&mut buf[6..8], rudder);
55:     LittleEndian::write_i16(&mut buf[8..10], 1024);
56:     buf[10] = signal_quality & 0x7F;
57:     buf
58: }
