60: fn make_battery_energy_summary_payload(
61:     soc: u8,
62:     voltage_v: f64,
63:     current_a: f64,
64:     temp_c: f64,
65: ) -> [u8; 12] {
66:     let mut buf = [0u8; 12];
67:     buf[0] = soc;
68:     LittleEndian::write_u16(&mut buf[1..3], (voltage_v * 1000.0).round() as u16);
69:     LittleEndian::write_u16(&mut buf[3..5], 3000);
70:     LittleEndian::write_u16(&mut buf[5..7], 3500);
71:     buf[7] = 4;
72:     let temp_dk = ((temp_c + 273.15) * 10.0).round() as i16;
73:     LittleEndian::write_i16(&mut buf[8..10], temp_dk);
74:     LittleEndian::write_u16(&mut buf[10..12], (current_a * 1000.0).round() as u16);
75:     buf
76: }
