78: fn make_battery_cells_payload(cells_mv: &[u16]) -> [u8; 34] {
79:     let mut buf = [0u8; 34];
80:     buf[0] = 85;
81:     let sum_v = cells_mv.iter().copied().sum::<u16>();
82:     LittleEndian::write_u16(&mut buf[1..3], sum_v);
83:     for (i, &mv) in cells_mv.iter().enumerate().take(14) {
84:         let offset = 3 + i * 2;
85:         LittleEndian::write_u16(&mut buf[offset..offset + 2], mv);
86:     }
87:     buf[31] = cells_mv.len() as u8;
88:     let temp_dk = ((25.0f64 + 273.15) * 10.0).round() as i16;
89:     LittleEndian::write_i16(&mut buf[32..34], temp_dk);
90:     buf
91: }
