121: fn test_dual_phase_monotonicity_ground_to_airborne() {
122:     let mut agg = TelemetryAggregator::new(None);
123: 
124:     // Phase 1: 30 ground OSD records (fly_time_s = 0.0, is_motor_up = false)
125:     for i in 0..30 {
126:         let payload = make_osd_payload(37.77, -122.41, 0.0, 0.0, 0.0, false, 6);
127:         let pt = agg.process_record(1, &payload).expect("OSD record parse failed").unwrap();
128:         assert_eq!(pt.fly_time_s, 0.0);
129:         assert!((pt.elapsed_s - i as f64 * 0.1).abs() < 1e-4);
130:     }
131: 
132:     // Phase 2: 50 airborne OSD records (fly_time_s = 0.1 .. 5.0, is_motor_up = true)
133:     for i in 1..=50 {
134:         let fly_time_s = i as f64 * 0.1;
135:         let payload = make_osd_payload(37.77 + i as f64 * 0.0001, -122.41, 10.0, fly_time_s, 5.0, true, 6);
136:         let pt = agg.process_record(1, &payload).expect("OSD record parse failed").unwrap();
137:         assert!((pt.fly_time_s - fly_time_s).abs() < 1e-4);
138:     }
139: 
140:     // Phase 3: 20 landing/ground OSD records (fly_time_s = 0.0, is_motor_up = false)
141:     for _ in 0..20 {
142:         let payload = make_osd_payload(37.77, -122.41, 0.0, 0.0, 0.0, false, 6);
143:         agg.process_record(1, &payload).expect("OSD record parse failed");
144:     }
145: 
146:     let dataset = agg.finish();
147:     assert_eq!(dataset.points.len(), 100);
148: 
149:     // Monotonicity verification
150:     for i in 1..dataset.points.len() {
151:         assert!(
152:             dataset.points[i].elapsed_s > dataset.points[i - 1].elapsed_s,
153:             "elapsed_s monotonicity failure at index {i}: {} <= {}",
154:             dataset.points[i].elapsed_s,
155:             dataset.points[i - 1].elapsed_s
156:         );
157:         assert!(
158:             dataset.points[i].timestamp_utc_ms > dataset.points[i - 1].timestamp_utc_ms,
159:             "timestamp_utc_ms monotonicity failure at index {i}: {} <= {}",
160:             dataset.points[i].timestamp_utc_ms,
161:             dataset.points[i - 1].timestamp_utc_ms
162:         );
163:     }
164: 
165:     // Takeoff transition verification at index 30
166:     assert!((dataset.points[30].elapsed_s - 3.1).abs() < 1e-4);
167: 
168:     // Exactly 1 Takeoff and 1 Landing event
169:     let takeoff_count = dataset
170:         .events
171:         .iter()
172:         .filter(|e| matches!(e.event_type, FlightEventType::Takeoff))
173:         .count();
174:     let landing_count = dataset
175:         .events
176:         .iter()
177:         .filter(|e| matches!(e.event_type, FlightEventType::Landing))
178:         .count();
179: 
180:     assert_eq!(takeoff_count, 1, "Must have exactly 1 Takeoff event");
181:     assert_eq!(landing_count, 1, "Must have exactly 1 Landing event");
182: }
